import Foundation
import Observation

/// Authors the rc files launchd runs.
///
/// The generated files still read `settings.env` and the theme's env at run
/// time rather than baking values in. That keeps borders correct at login even
/// if the app never starts — the GUI must never be in the boot path — while
/// still making the app the single author of the file itself.
@MainActor
@Observable
final class RCGenerator {
    private(set) var lastOutcomes: [String: GeneratedFile.Outcome] = [:]

    private let log: CommandLog
    init(log: CommandLog) { self.log = log }

    static var bordersrc: GeneratedFile {
        GeneratedFile(url: Paths.home.appending(path: ".config/borders/bordersrc"))
    }

    static var yabairc: GeneratedFile {
        GeneratedFile(url: Paths.home.appending(path: ".config/yabai/yabairc"))
    }

    var driftedFiles: [String] {
        [Self.bordersrc, Self.yabairc]
            .filter(\.hasDrifted)
            .map { $0.url.lastPathComponent }
    }

    private static let header = """
    #!/bin/bash
    # Generated by Macarchy Settings — edits here are reported, not silently kept.
    #
    # Values still resolve at run time from settings.env and the active theme, so
    # this works at login whether or not the app is running. Regions marked
    # "macarchy:keep" are preserved across regeneration.

    """

    // MARK: - bordersrc

    func generateBordersRC() {
        let file = Self.bordersrc
        let kept = file.preservedRegions()
        let extra = kept["extra"].map { "\n\(GeneratedFile.beginKeep) extra\n\($0)\n\(GeneratedFile.endKeep)\n" } ?? """

        \(GeneratedFile.beginKeep) extra
        \(GeneratedFile.endKeep)

        """

        let content = Self.header + """
        set -euo pipefail

        BORDERS_BIN="/opt/homebrew/opt/borders/bin/borders"
        # Local renderer keeps square borders rectangular on translucent windows.
        if [ -x "$HOME/.local/bin/macarchy-borders" ]; then
          BORDERS_BIN="$HOME/.local/bin/macarchy-borders"
        fi

        THEMES_DIR="$HOME/.config/macarchy-settings/themes"
        CURRENT_THEME="$(cat "$THEMES_DIR/.current" 2>/dev/null || true)"
        if [ -n "$CURRENT_THEME" ] && [ -f "$THEMES_DIR/$CURRENT_THEME/theme.env" ]; then
          # shellcheck source=/dev/null
          source "$THEMES_DIR/$CURRENT_THEME/theme.env"
        fi

        SETTINGS_ENV="$HOME/.config/macarchy-settings/settings.env"
        if [ -f "$SETTINGS_ENV" ]; then
          # shellcheck source=/dev/null
          source "$SETTINGS_ENV"
        fi

        # Theme owns colour; settings owns geometry. Defaults only apply if neither set it.
        BORDER_STYLE="${BORDER_STYLE:-square}"
        BORDER_ACTIVE="${BORDER_ACTIVE:-0xff45e8ff}"
        BORDER_INACTIVE="${BORDER_INACTIVE:-0x00000000}"
        BORDER_WIDTH="${BORDER_WIDTH:-6.0}"
        BORDERS_VISIBLE="${BORDERS_VISIBLE:-true}"
        BORDERS_BLACKLIST="${BORDERS_BLACKLIST:-}"

        case ",$BORDERS_BLACKLIST," in
          *",iPhone Mirroring,"*) ;;
          ",,") BORDERS_BLACKLIST="iPhone Mirroring" ;;
          *) BORDERS_BLACKLIST="$BORDERS_BLACKLIST,iPhone Mirroring" ;;
        esac

        if [ "$BORDERS_VISIBLE" != "true" ]; then
          BORDER_ACTIVE="0x00000000"
          BORDER_INACTIVE="0x00000000"
          BORDER_WIDTH="0.0"
          BORDER_ANIMATION_COLORS=""
        fi

        if [ -n "${BORDER_ANIMATION_COLORS:-}" ]; then
          read -r -a BORDER_COLORS <<< "$BORDER_ANIMATION_COLORS"
          FIRST="${BORDER_COLORS[0]}"
          SECOND="${BORDER_COLORS[3]:-${BORDER_COLORS[1]:-$FIRST}}"
          if [ "${BORDER_ANIMATION_EFFECT:-glow}" = "glow" ]; then
            ACTIVE_ARG="active_color=glow($FIRST)"
          else
            ACTIVE_ARG="active_color=gradient(top_left=$FIRST,bottom_right=$SECOND)"
          fi
        else
          ACTIVE_ARG="active_color=$BORDER_ACTIVE"
        fi
        \(extra)
        exec "$BORDERS_BIN" \\
          style="$BORDER_STYLE" \\
          width="$BORDER_WIDTH" \\
          hidpi=on \\
          background_color=0x00000000 \\
          "$ACTIVE_ARG" \\
          inactive_color="$BORDER_INACTIVE" \\
          blacklist="$BORDERS_BLACKLIST"

        """

        record("bordersrc", file.write(content, reason: "borders settings changed"))
    }

    private func record(_ name: String, _ outcome: GeneratedFile.Outcome) {
        lastOutcomes[name] = outcome
        switch outcome {
        case .unchanged:
            break
        case .written:
            log.note("generated \(name)", "")
        case .writtenOverDrift(let snapshot):
            log.note("generated \(name)", "hand edits found — snapshotted as \(snapshot ?? "?")")
        case .failed(let message):
            log.note("generating \(name) failed", message)
        }
    }
}
